                    "type": "message",
                    "role": "assistant",
                    "content": [],
                    "model": model,
                    "stop_reason": None,
                    "usage": {"input_tokens": 0, "output_tokens": 0},
                },
            })
        elif delta.get("content") is not None:
            # Content chunk
            text = delta.get("content", "")
