def _emit_anthropic_sse(self, oai_data, model, blocks_started):
    """Convert one OpenAI streaming chunk to Anthropic SSE events.
    Handles both reasoning_content (thinking block) and content (text block).
    blocks_started: dict with 'thinking' and 'text' bool keys.
    Returns updated blocks_started.
    """
    choice = oai_data.get("choices", [{}])[0]
    delta = choice.get("delta", {})
    finish_reason = choice.get("finish_reason")

    if delta.get("role") == "assistant":
        # message_start - first chunk with role
        self._write_sse("message_start", {
            "type": "message_start",
            "message": {
                "id": oai_data.get("id", "msg_sensenova"),
                "type": "message",
                "role": "assistant",
                "content": [],
                "model": model,
                "stop_reason": None,
                "usage": {"input_tokens": 0, "output_tokens": 0},
            },
        })

    # Reasoning content -> thinking block (index 0)
    reasoning = delta.get("reasoning_content")
    if reasoning:
        if not blocks_started["thinking"]:
            self._write_sse("content_block_start", {
                "type": "content_block_start",
                "index": 0,
                "content_block": {"type": "thinking", "thinking": ""},
            })
            blocks_started["thinking"] = True
        self._write_sse("content_block_delta", {
            "type": "content_block_delta",
            "index": 0,
            "delta": {"type": "thinking_delta", "thinking": reasoning},
        })

    # Text content -> text block (index 1 if thinking came first, else 0)
    content = delta.get("content")
    if content is not None:
        text = content
        text_index = 1 if blocks_started["thinking"] else 0
        if not blocks_started["text"] and text:
            self._write_sse("content_block_start", {
                "type": "content_block_start",
                "index": text_index,
                "content_block": {"type": "text", "text": ""},
            })
            blocks_started["text"] = True
        if text:
            self._write_sse("content_block_delta", {
                "type": "content_block_delta",
                "index": text_index,
                "delta": {"type": "text_delta", "text": text},
            })

    if finish_reason:
        # Emit message_delta before message_stop
        self._write_sse("message_delta", {
            "type": "message_delta",
            "delta": {
                "stop_reason": _map_stop_reason(finish_reason),
                "stop_sequence": None,
            },
            "usage": {"output_tokens": 0},
        })

    return blocks_started

