# Copy messages
for msg in body.get("messages", []):
    role = msg["role"]
    content = msg.get("content", "")
    if isinstance(content, list):
        # Anthropic content blocks -> extract text (also handle thinking blocks)
        texts = []
        for c in content:
            if c.get("type") == "text":
                texts.append(c["text"])
            elif c.get("type") == "thinking":
                texts.append(f"[thinking]{c['thinking']}[/thinking]")
        content = "\n".join(texts)
    messages.append({"role": role, "content": content})

