def _handle_streaming(self, resp, model):
    self.send_response(200)
    self.send_header("Content-Type", "text/event-stream")
    self.send_header("Cache-Control", "no-cache")
    self.send_header("Connection", "keep-alive")
    self.end_headers()

    # State machine for Anthropic SSE content block lifecycle.
    # Each content block MUST follow: start → delta* → stop
    # Blocks are indexed sequentially: 0, 1, 2...
    block_index = -1      # index of currently active block (-1 = none)
    block_type = None     # "thinking" or "text" — type of active block

    try:
        buffer = b""
        while True:
            chunk = resp.read(4096)
            if not chunk:
                break
            buffer += chunk
            while b"\n" in buffer:
                line, buffer = buffer.split(b"\n", 1)
                line = line.decode("utf-8", errors="replace").strip()
                if not line or line.startswith(":"):
                    continue
                if line.startswith("data: "):
                    data_str = line[6:]
                    if data_str.strip() == "[DONE]":
                        break
                    try:
                        oai_data = json.loads(data_str)
                        if not oai_data.get("choices"):
                            continue
                        block_index, block_type = self._stream_process_chunk(
                            oai_data, model, block_index, block_type
                        )
                    except json.JSONDecodeError:
                        pass
            if b"[DONE]" in buffer:
                break
    except (BrokenPipeError, ConnectionResetError):
        return
    except Exception as e:
        print(f"Stream error: {e}", flush=True)
    finally:
        resp.close()

    # Close any open block
    if block_index >= 0:
        self._write_sse("content_block_stop", {
            "type": "content_block_stop", "index": block_index,
        })

    # Final message_stop
    try:
        self.wfile.write(
            f"event: message_stop\ndata: {json.dumps({'type': 'message_stop'})}\n\n".encode()
        )
        self.wfile.flush()
    except (BrokenPipeError, ConnectionResetError):
        pass

def _stream_process_chunk(self, oai_data, model, block_index, block_type):
    """Process one OpenAI streaming chunk, managing the block lifecycle.

    Lifecycle rules:
      - reasoning_content → start/continue "thinking" block
      - reasoning (no reasoning_content) → start/continue "text" block (flash-lite)
      - content → close thinking if open, start/continue text block
      - finish_reason → close current block, emit message_delta

    Returns (block_index, block_type) after processing.
    """
    choice = oai_data["choices"][0]
    delta = choice.get("delta", {})
    finish_reason = choice.get("finish_reason")

    # ── message_start ──
    if delta.get("role") == "assistant":
        self._write_sse("message_start", {
            "type": "message_start",
            "message": {
                "id": oai_data.get("id", "msg_sensenova"),
                "type": "message", "role": "assistant",
                "content": [], "model": model,
                "stop_reason": None,
                "usage": {"input_tokens": 0, "output_tokens": 0},
            },
        })

    # ── reasoning_content → thinking block ──
    reasoning = delta.get("reasoning_content")
    if reasoning:
        if block_index < 0 or block_type != "thinking":
            # Close whatever block was open
            if block_index >= 0:
                self._write_sse("content_block_stop", {
                    "type": "content_block_stop", "index": block_index,
                })
            block_index += 1
            block_type = "thinking"
            self._write_sse("content_block_start", {
                "type": "content_block_start", "index": block_index,
                "content_block": {"type": "thinking", "thinking": ""},
            })
        self._write_sse("content_block_delta", {
            "type": "content_block_delta", "index": block_index,
            "delta": {"type": "thinking_delta", "thinking": reasoning},
        })

    # ── reasoning (no reasoning_content) → text block (flash-lite) ──
    reasoning_alt = delta.get("reasoning")
    if reasoning_alt and not reasoning:
        if block_index < 0 or block_type != "text":
            if block_index >= 0:
                self._write_sse("content_block_stop", {
                    "type": "content_block_stop", "index": block_index,
                })
            block_index += 1
            block_type = "text"
            self._write_sse("content_block_start", {
                "type": "content_block_start", "index": block_index,
                "content_block": {"type": "text", "text": ""},
            })
        self._write_sse("content_block_delta", {
            "type": "content_block_delta", "index": block_index,
            "delta": {"type": "text_delta", "text": reasoning_alt},
        })

    # ── content → text block (ds4f style) ──
    content = delta.get("content")
    if content is not None:
        text = content
        if text:
            if block_index < 0 or block_type != "text":
                if block_index >= 0:
                    self._write_sse("content_block_stop", {
                        "type": "content_block_stop", "index": block_index,
                    })
                block_index += 1
                block_type = "text"
                self._write_sse("content_block_start", {
                    "type": "content_block_start", "index": block_index,
                    "content_block": {"type": "text", "text": ""},
                })
            self._write_sse("content_block_delta", {
                "type": "content_block_delta", "index": block_index,
                "delta": {"type": "text_delta", "text": text},
            })

    # ── finish_reason → close block, emit message_delta ──
    if finish_reason:
        if block_index >= 0:
            self._write_sse("content_block_stop", {
                "type": "content_block_stop", "index": block_index,
            })
            block_index = -1
            block_type = None
        self._write_sse("message_delta", {
            "type": "message_delta",
            "delta": {
                "stop_reason": _map_stop_reason(finish_reason),
                "stop_sequence": None,
            },
            "usage": {"output_tokens": 0},
        })

    return block_index, block_type

