                if block_index >= 0:
                    self._write_sse("content_block_stop", {
                        "type": "content_block_stop", "index": block_index,
                    })
                block_index += 1
                block_type = "text"
                self._write_sse("content_block_start", {
                    "type": "content_block_start", "index": block_index,
                    "content_block": {"type": "text", "text": ""},
                })
