                "type": "content_block_delta", "index": block_index,
                "delta": {"type": "text_delta", "text": text},
            })

    # ── finish_reason → close block, emit message_delta ──
    if finish_reason:
        if block_index >= 0:
            self._write_sse("content_block_stop", {
                "type": "content_block_stop", "index": block_index,
            })
            block_index = -1
            block_type = None
